INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7166584, 1100432, 150277, '<td valign="top">The tree is quite pretty, but I do find the light a bit garish.</td>', 'The tree is quite pretty, but I do find the light a bit garish.', '2014-01-31 19:39:58.000000', NULL, 1),
(7166585, 1100282, 150277, '<td valign="top">Gorgeous.  And that wind at the top of the mountain, definitely cold.</td>', 'Gorgeous.  And that wind at the top of the mountain, definitely cold.', '2014-01-31 19:40:41.000000', NULL, 1),
(7166591, 1100256, 150277, '<td valign="top">Nice original idea.  Not terribly pretty, but bonus points for creativity.</td>', 'Nice original idea.  Not terribly pretty, but bonus points for creativity.', '2014-01-31 19:42:14.000000', NULL, 1),
(7166593, 1100342, 150277, '<td valign="top">Wow.  This is just stunning, and it definitely looks cold.</td>', 'Wow.  This is just stunning, and it definitely looks cold.', '2014-01-31 19:43:19.000000', NULL, 1),
(7166595, 1100286, 150277, '<td valign="top">Great shot.  Cold indeed.</td>', 'Great shot.  Cold indeed.', '2014-01-31 19:43:47.000000', NULL, 1),
(7166603, 1099888, 150277, '<td valign="top">Great photo.  Ice fishing exemplifies the pinnacle of cold if you ask me.</td>', 'Great photo.  Ice fishing exemplifies the pinnacle of cold if you ask me.', '2014-01-31 19:46:12.000000', NULL, 1),
(7166605, 1100346, 150277, '<td valign="top">Wowzers - totally cool.  Nice capture.</td>', 'Wowzers - totally cool.  Nice capture.', '2014-01-31 19:47:11.000000', NULL, 1),
(7166608, 1100182, 150277, '<td valign="top">Nice.  I love the snow that is visible on the dock.  Just an all around interesting photo.</td>', 'Nice.  I love the snow that is visible on the dock.  Just an all around interesting photo.', '2014-01-31 19:49:00.000000', NULL, 1),
(7166610, 1100430, 150277, '<td valign="top">Neat.  I like the framing and the reflection.</td>', 'Neat.  I like the framing and the reflection.', '2014-01-31 19:49:57.000000', NULL, 1),
(7166611, 1099800, 150277, '<td valign="top">Beautiful capture of a cold day in the city.</td>', 'Beautiful capture of a cold day in the city.', '2014-01-31 19:51:05.000000', NULL, 1),
(7166612, 1100181, 150277, '<td valign="top">Very pretty.  What is mixed in with the peas?</td>', 'Very pretty.  What is mixed in with the peas?', '2014-01-31 19:52:56.000000', NULL, 1),
(7166718, 1099800, 31637, '<td valign="top">Brilliant street photography. The composition is excellent, and the exposure is superb. I love this night shot in black and white. 8</td>', 'Brilliant street photography. The composition is excellent, and the exposure is superb. I love this night shot in black and white. 8', '2014-02-01 00:39:50.000000', NULL, 1),
(7166720, 1099916, 31637, '<td valign="top">Hope this 9 contributes to your ribbon! Which it deserves :) Good Luck.</td>', 'Hope this 9 contributes to your ribbon! Which it deserves :) Good Luck.', '2014-02-01 00:41:13.000000', NULL, 1),
(7166721, 1100242, 31637, '<td valign="top">More like Summer...I am sorry I cannot rate this higher than a 5.</td>', 'More like Summer...I am sorry I cannot rate this higher than a 5.', '2014-02-01 00:41:47.000000', NULL, 1),
(7166723, 1100253, 31637, '<td valign="top">I love the feel of this shot. It transports me. However, it doesn''t convey cold. 6</td>', 'I love the feel of this shot. It transports me. However, it doesn''t convey cold. 6', '2014-02-01 00:42:53.000000', NULL, 1),
(7166726, 1100182, 31637, '<td valign="top">Colors are over-processed</td>', 'Colors are over-processed', '2014-02-01 00:43:32.000000', NULL, 1),
